import requests

def get_channels():
    # Replace with your actual API endpoint and token
    url = "https://your-slack-api.com/channels"
    token = "your-slack-token"
    headers = {"Authorization": f"Bearer {token}"}
    response = requests.get(url, headers=headers)
    return response.json()["channels"]

def read_channel_messages(channel):
    # Replace with your actual API endpoint and token
    url = f"https://your-slack-api.com/channels/{channel}/messages"
    token = "your-slack-token"
    headers = {"Authorization": f"Bearer {token}"}
    response = requests.get(url, headers=headers)
    return response.json()["messages"]

def send_direct_message(recipient, body):
    # Replace with your actual API endpoint and token
    url = "https://your-slack-api.com/direct-messages"
    token = "your-slack-token"
    headers = {"Authorization": f"Bearer {token}"}
    data = {"recipient": recipient, "body": body}
    response = requests.post(url, headers=headers, json=data)
    return response.json()

def main():
    channels = get_channels()
    user_message_count = {}

    for channel in channels:
        messages = read_channel_messages(channel)
        for message in messages:
            user = message["user"]
            if user not in user_message_count:
                user_message_count[user] = 0
            user_message_count[user] += 1

    sorted_users = sorted(user_message_count.items(), key=lambda x: (-x[1], x[0]))

    for i, (user, count) in enumerate(sorted_users):
        send_direct_message(user, f"Congrats on being the {i+1}-th most active user!")

if __name__ == "__main__":
    main()
